import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Box, TextField, Button, Typography, Alert, CircularProgress, InputAdornment, IconButton } from '@mui/material';
import PersonIcon from '@mui/icons-material/Person';
import EmailIcon from '@mui/icons-material/Email';
import VisibilityIcon from '@mui/icons-material/Visibility';
import VisibilityOffIcon from '@mui/icons-material/VisibilityOff';
import { utilisateurService } from '../services/utilisateurService';

const Register: React.FC = () => {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [showPassword, setShowPassword] = useState(false);
    const [form, setForm] = useState({ pseudo: '', email: '', password: '' });

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setForm({ ...form, [e.target.name]: e.target.value });
        setError(null);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        
        if (!form.pseudo || !form.email || !form.password) {
            setError('Veuillez remplir tous les champs');
            return;
        }
        
        if (form.password.length < 6) {
            setError('Le mot de passe doit contenir au moins 6 caractères');
            return;
        }
        
        setLoading(true);
        
        try {
            const response = await utilisateurService.inscription({
                pseudo: form.pseudo,
                email: form.email,
                mot_de_passe: form.password
            });
            localStorage.setItem('userId', response.data.utilisateurId.toString());
            navigate('/profil');
        } catch (err: any) {
            setError(err.response?.data?.error || 'Erreur lors de l\'inscription');
        } finally {
            setLoading(false);
        }
    };

    const textFieldSx = {
        '& .MuiInputBase-root': {
            height: '37px',
            backgroundColor: '#a9a9a9',
            borderRadius: '15px',
            '& fieldset': { border: 'none' }
        },
        '& .MuiInputBase-input': { padding: '0 45px 0 15px', fontFamily: 'Poppins', fontSize: '14px', color: '#333' }
    };

    return (
        <Box sx={{ minHeight: '100vh', background: 'linear-gradient(180deg, #ffffff 1%, #cfcfcf 43%, #999999 100%)', display: 'flex', alignItems: 'center', justifyContent: 'center', position: 'relative' }}>
            <Box sx={{ position: 'absolute', left: '28px', top: '0' }}><img src="/Icons/logo.png" alt="Logo" /></Box>
            <Box sx={{ position: 'absolute', left: '135px', top: '192px', width: '400px', height: '400px' }}><img src="/Icons/register.png" alt="Illustration" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /></Box>
            
            <Box sx={{ position: 'absolute', left: '715px', top: '203px', width: '379px' }}>
                <Typography variant="h4" sx={{ fontFamily: 'Poppins', fontWeight: 800, fontSize: '32px', background: 'linear-gradient(34deg, #000204 0%, #773399 100%)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', textAlign: 'center', mb: '30px' }}>
                    Créer un compte
                </Typography>
                
                {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
                
                <form onSubmit={handleSubmit}>
                    <Box sx={{ mb: '25px' }}>
                        <Typography sx={{ fontFamily: 'Poppins', fontSize: '14px', color: '#333', mb: '8px' }}>Pseudo</Typography>
                        <TextField fullWidth name="pseudo" placeholder="Votre pseudo" value={form.pseudo} onChange={handleChange} required sx={textFieldSx} slotProps={{ input: { endAdornment: <InputAdornment position="end"><PersonIcon sx={{ color: '#666' }} /></InputAdornment> } }} />
                    </Box>
                    
                    <Box sx={{ mb: '25px' }}>
                        <Typography sx={{ fontFamily: 'Poppins', fontSize: '14px', color: '#333', mb: '8px' }}>Email</Typography>
                        <TextField fullWidth name="email" type="email" placeholder="Votre email" value={form.email} onChange={handleChange} required sx={textFieldSx} slotProps={{ input: { endAdornment: <InputAdornment position="end"><EmailIcon sx={{ color: '#666' }} /></InputAdornment> } }} />
                    </Box>
                    
                    <Box sx={{ mb: '25px' }}>
                        <Typography sx={{ fontFamily: 'Poppins', fontSize: '14px', color: '#333', mb: '8px' }}>Mot de passe</Typography>
                        <TextField fullWidth name="password" type={showPassword ? 'text' : 'password'} placeholder="Votre mot de passe" value={form.password} onChange={handleChange} required sx={textFieldSx} slotProps={{ input: { endAdornment: <InputAdornment position="end"><IconButton onClick={() => setShowPassword(!showPassword)} edge="end">{showPassword ? <VisibilityOffIcon /> : <VisibilityIcon />}</IconButton></InputAdornment> } }} />
                    </Box>
                    
                    <Button type="submit" disabled={loading} sx={{ width: '238px', height: '50px', background: 'linear-gradient(0deg, #01111d 0%, #773399 100%)', borderRadius: '45px', fontWeight: 800, fontSize: '20px', color: 'white', margin: '15px auto', display: 'block', '&:hover': { opacity: 0.9, transform: 'translateY(-2px)' } }}>
                        {loading ? <CircularProgress size={28} /> : 'Créer'}
                    </Button>
                    
                    <Box sx={{ textAlign: 'center' }}>
                        <Typography component="a" href="/login" sx={{ color: '#333', textDecoration: 'none', '&:hover': { color: '#773399' } }}>Déjà un compte ? Se connecter</Typography>
                    </Box>
                </form>
            </Box>
        </Box>
    );
};

export default Register;
